insert into question_bank (id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id)
select id, chapter_id, subject_id, stem, options, answer_index, explanation, images, source, difficulty, concept_id
from jsonb_to_recordset($json$[{"id":"che-pe-149","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"On moving from left to right across a period, the atomic radius of the elements generally","options":["increases","decreases","remains exactly constant","becomes infinite"],"answer_index":1,"explanation":"Rising effective nuclear charge pulls the same-shell electrons inward, so the atom shrinks.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-150","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"On descending a group, the atomic radius of the elements generally","options":["decreases","increases","becomes zero","is independent of the new shell"],"answer_index":1,"explanation":"Each step down adds a principal shell, which outweighs the extra nuclear charge.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-151","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"A cation is always smaller than the parent atom from which it is formed because","options":["a new shell is added","electrons are lost and the remaining cloud is held more tightly","nuclear charge decreases","the ion gains extra shielding"],"answer_index":1,"explanation":"Fewer electrons and a higher Zeff/electron ratio contract the ion relative to the atom.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-152","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"An anion is always larger than the parent atom from which it is formed because","options":["nuclear charge increases","extra electrons raise inter-electronic repulsion and the cloud expands","a shell is completely removed","the ion has fewer electrons than the atom"],"answer_index":1,"explanation":"The added electron(s) swell the electron cloud, so r(anion) > r(atom).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-153","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The covalent radius of an atom is half the internuclear distance in a","options":["heteronuclear ionic crystal","homonuclear single-bonded molecule","van der Waals contact between two non-bonded atoms","metallic unit cell only"],"answer_index":1,"explanation":"In Cl₂, for example, r(cov) = ½ d(Cl–Cl).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-154","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"For the same element the van der Waals radius compared with the covalent radius is","options":["smaller","larger","exactly equal","undefined"],"answer_index":1,"explanation":"van der Waals contact is a non-bonded approach, so the apparent radius is greater than the bonded covalent radius.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-155","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The steady rise of effective nuclear charge across a period pulls the electron cloud inward and therefore","options":["expands the atom","shrinks the atom","adds a new shell","creates an anion"],"answer_index":1,"explanation":"Zeff increases left to right while n stays the same, so atomic size falls.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-156","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Addition of a new principal shell is the main reason atomic size","options":["falls across a period","grows down a group","is identical for all metals","vanishes for noble gases"],"answer_index":1,"explanation":"The extra shell lies farther from the nucleus, so group radii increase top to bottom.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-157","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Metallic radius is half the distance between neighbouring nuclei in a","options":["gaseous homonuclear molecule","metallic crystal","van der Waals dimer","hydrated ion"],"answer_index":1,"explanation":"It is the radius used for metals in the close-packed or body-centred lattice.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-158","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Isoelectronic species are atoms or ions that contain","options":["the same number of protons","the same number of electrons","the same mass number","identical nuclear charges"],"answer_index":1,"explanation":"N³⁻, O²⁻, F⁻, Ne, Na⁺ and Mg²⁺ are a familiar isoelectronic set (10 electrons).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-159","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In an isoelectronic series the ionic radius falls as the","options":["nuclear charge falls","nuclear charge rises","mass number falls","neutron count rises"],"answer_index":1,"explanation":"More protons pull the same number of electrons more tightly, so size decreases with Z.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-160","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The fluoride ion is larger than a neutral fluorine atom because of","options":["loss of the 2p electron","extra electron–electron repulsion in F⁻","a decrease in nuclear charge","lanthanoid contraction"],"answer_index":1,"explanation":"Adding one electron to F expands the 2p cloud, so r(F⁻) > r(F).","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"atomic-ionic-radius","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
